"""Append bounded source assessments. Never fabricate final or independent decisions."""
import csv,json,hashlib,re,os
from pathlib import Path
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[1];E=R/'evidence';TS=datetime.now(timezone.utc).isoformat(timespec='seconds')
def read(n):return list(csv.DictReader((E/n).open())) if (E/n).exists() else []
def write(n,rows,fields=None):
 fields=fields or list(dict.fromkeys(k for r in rows for k in r))
 with (E/n).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
records=read('records.csv');by={r['record_id']:r for r in records}
papers=[
 dict(id='GB-P006',record='GB-R00017',key='paella',title='Paella: Low-latency Model Serving with Software-defined GPU Scheduling',doi='10.1145/3600006.3613163',url='https://kelvin-ng.github.io/assets/sosp2023-final224.pdf',year='2023',venue='SOSP 2023',authors='Kelvin K.W. Ng; Henri Maxime Demoulin; Vincent Liu',anchor='printed pp604-606; PDF pp10-12; sections7.1-7.3',mechanism='Instrumented kernels; software scheduling',gpu='Tesla T4',software='Linux4.15.0;CUDA11.7;TVM0.10.0',workload='Mixed inference; lognormal arrivals sigma1.5/2',baseline='CUDA-MS;Triton23.03;Paella ablations',limit='Warmup excluded; TVM wrapper; MPS omitted from eight-model experiment',tradeoff='Fairness versus short-job latency; instrumentation cost',scores=[2,2,1,2,1,2,2,2,1,2],qa=['Explicit goal','Mechanism classifiable','Repetition count unclear','Versioned setup','Wrapper caveat','Defined throughput','p99 specified','Mixed jobs tested','Fairness only','Artifact and limits'],outcomes=[('ResNet18+InceptionV3;lognormal sigma1.5/2','CUDA-MS','ResNet18 p99 reduction factor','up to3','x','printed p604 section7.1/Fig12; PDF pp10-11','Author-reported approximate maximum; not uniform across loads'),('Empty kernel;160 blocks;instrumentation with aggregation','Uninstrumented kernel','p90 instrumentation overhead','6.6','microseconds','printed p606 section7.3/Fig15; PDF p12','Microbenchmark; not inference request latency')]),
 dict(id='GB-P007',record='GB-R00088',key='orion',title='Orion: Interference-aware, Fine-grained GPU Sharing for ML Applications',doi='10.1145/3627703.3629578',url='https://anakli.inf.ethz.ch/papers/orion_eurosys24.pdf',year='2024',venue='EuroSys 2024',authors='Foteini Strati; Xianzhe Ma; Ana Klimovic',anchor='printed pp1082-1087; PDF pp8-13; sections6-7',mechanism='Interception; interference-aware kernel scheduling',gpu='V10016GB;A10040GB extension',software='PyTorch1.12;Python3.9;CUDA10.2/11.3',workload='High-priority plus best-effort inference;Poisson',baseline='Dedicated high-priority GPU;MPS;Streams;REEF-N policy',limit='Trusted clients; no secure isolation; offline profiling; REEF-N reimplementation',tradeoff='Tail latency versus best-effort progress',scores=[2,2,2,2,1,2,2,2,2,2],qa=['Explicit goal','Interception specified','Three repetitions','Versioned setup','Reimplemented comparator','Defined aggregate metric','p99 and arrivals','Collocations tested','Trust boundary explicit','Artifact and limitations'],outcomes=[('Two inference clients;Poisson;V100','Dedicated high-priority inference','Aggregate throughput ratio','up to7.3','x','printed p1086 section6.2.3/Fig12; PDF p12','Maximum; includes best-effort work'),('Two inference clients;Poisson;V100','Dedicated high-priority inference','High-priority p99 overhead','15','percent','printed p1086 section6.2.3/Fig12; PDF p12','Authors summarize within15%; averaged across collocations, not worst-case guarantee')]),
 dict(id='GB-P008',record='GB-R00077',key='gslice',title='GSLICE: Controlled Spatial Sharing of GPUs for a Scalable Inference Platform',doi='10.1145/3419111.3421284',url='https://par.nsf.gov/servlets/purl/10299299',year='2020',venue='SoCC 2020',authors='Aditya Dhakal; Sameer G Kulkarni; K.K. Ramakrishnan',anchor='printed pp499-501; PDF pp8-10; sections4.1-4.3',mechanism='MPS allocation; adaptive batching',gpu='One V10016GB',software='Linux4.4.0-150;DPDK19.02;CNTK/PyTorch/TensorRT',workload='Concurrent inference functions;25ms target',baseline='Default MPS;MPS+SLAB;TensorRT19.02',limit='GUE is composite, not hardware utilization percentage; no extracted tail percentile',tradeoff='Batching/fairness versus individual latency',scores=[2,2,1,2,2,2,1,2,1,1],qa=['Explicit goal','Sharing described','Confidence intervals; counts unclear','Hardware and OS','Comparator scope stated','GUE defined','Tail statistic unclear','Concurrent functions','Performance scope','Reproduction incomplete'],outcomes=[('Alexnet+ResNet50;25ms target','Default MPS GUE38.82','GPU utilization efficacy GUE','94.04','composite score','printed p500 Table3; PDF p9','Not percent GPU utilization'),('ResNet50;batch1;GPU-ready batch execution','TensorRT server19.02','Signed latency improvement','-7.52','percent','printed p501 Table4; PDF p10','Negative means worse latency; excludes transport overhead; single-model comparison')]),
 dict(id='GB-P009',record='GB-R02275',key='clockwork',title='Serving DNNs like Clockwork: Performance Predictability from the Bottom Up',doi='',url='https://people.mpi-sws.org/~antoinek/documents/20osdi_clockwork.pdf',year='2020',venue='USENIX OSDI 2020',authors='Arpan Gujarati; Reza Karimi; Safya Alzayat; Wei Hao; Antoine Kaufmann; Ymir Vigfusson; Jonathan Mace',anchor='printed pp451-452; author PDF pp9-10; section6.1/Fig5',mechanism='Predictable temporal scheduling',gpu='One V10032GB in section6.1',software='Not extracted',workload='15 ResNet50 instances;16 closed-loop clients/model',baseline='Clipper;INFaaS (different EC2 hardware)',limit='INFaaS comparison qualitative; fault tolerance unaddressed',tradeoff='Predictability versus admission and concurrency',scores=[2,2,1,1,1,2,2,2,1,2],qa=['Explicit goal','Scheduling described','Repetition count unclear','Versions not extracted','Hardware mismatch disclosed','Goodput defined','SLO and CDF','Contending models','No fault guarantee','Artifact and limits'],outcomes=[('15 ResNet50 instances;16 clients/model;500ms SLO','INFaaS on nonidentical EC2 setup','Clockwork goodput','approximately800','requests/second','printed p452 section6.1/Fig5; author PDF p10','Within-SLO successes; comparator qualitative; not total throughput'),('15 ResNet50 instances;16 clients/model;500ms SLO','No comparative ratio','Clockwork request latency','approximately300','milliseconds','printed p452 section6.1/Fig5; author PDF p10','Batch16 scheduling explanation; not a p99 value')])
]
def assess(selected):
 checks=read('fulltext_checks.csv');forms=read('study_extraction_form.csv');qa=read('quality.csv');ex=read('extraction.csv');criteria=read('fulltext_criteria.csv');tasks=read('report_validation_queue.csv');links=read('report_record_links.csv');retr=read('cycle3_retrieval.csv')
 for p in papers:
  if p['key'] not in selected or any(x['report_id']==p['id'] for x in checks):continue
  rid=p['id'];assert p['record'] in by
  # The downloaded author manuscript is checked against the venue/DOI shown in its first page.
  pdf=Path(os.environ.get('OS_CEP_SOURCE_DIR','/tmp/c3-sources'))/(p['key']+'.pdf');assert pdf.exists()
  checks.append(dict(report_id=rid,short_name=p['key'],doi=p['doi'],source=p['url'],anchor=p['anchor'],first_reviewer_recommendation='provisionally_eligible',criterion_rationale='IC1-IC6 supported in checked source sections; eligible recommendation only.',remaining_checks='Independent eligibility, numeric and QA verification; complete remaining fields.',reviewer='Codex-GroupB',date=TS[:10],second_vote='',final_decision='pending'))
  form=dict.fromkeys(forms[0],'not_extracted');form.update(report_id=rid,study_id='GB-PS'+rid[-3:],title=p['title'],doi=p['doi'],source=p['url'],source_anchor=p['anchor'],mechanism=p['mechanism'],gpu_hardware=p['gpu'],driver_runtime=p['software'],models=p['workload'],tenant_mix=p['workload'],baseline=p['baseline'],metric_outcomes_register='extraction.csv:'+rid,limitations=p['limit'],tradeoffs=p['tradeoff'],eligibility_status='provisionally_eligible;study_identity_provisional',reviewer='Codex-GroupB',independent_checker='',field_status='Selected fields checked; other fields not_extracted',checked_at_utc=TS,authors=p['authors'],year=p['year'],venue=p['venue']);forms.append(form)
  qa_anchors={
   'paella':['p595 section1','pp599-603 sections4-6','p604 methodology','p604 methodology','p604 Table3/baselines','pp604-605 Figs11-12','pp604-605 Figs11-12','p605 Figs12-13','pp606-607 discussion;scope provisional','pp606-607 section8'],
   'orion':['p1075 section1','pp1079-1082 sections4-5','p1082 section6.1','p1082 section6.1','p1083 baselines','p1086 section6.2.3','p1086 section6.2.3','p1086 section6.3','p1087 section7 Security','p1087 section7;artifact appendix'],
   'gslice':['p492 introduction','pp495-499 section3','p500 error bars;section4','pp499-500 testbed','p501 section4.3','p494 GUE definition;p500 Table3','pp500-501 latency plots','p500 section4.2','pp496-498 resource controls;p502 performance isolation','pp499-504 implementation/evaluation/limits'],
   'clockwork':['p443 introduction','pp448-451 sections4-5','p451 section6 setup','p451 section6 setup','p451 section6.1 mismatch','p452 goodput definition','pp451-452 Fig5','p451 section6.1','pp455-456 discussion','pp455-456 discussion;artifact appendix']}
  for i,(score,reason) in enumerate(zip(p['scores'],p['qa']),1):
   maximum=2
   if p['key']=='paella' and i==9:score='NA';maximum=0;reason='No security/fault or resource-isolation guarantee appraised; fairness is assessed under Q8; N/A provisional'
   if p['key']=='gslice' and i==9:score=2;reason='Fixed quotas and performance-isolation tests; no stronger security claim inferred'
   qa.append(dict(report_id=rid,criterion='Q'+str(i),score=score,maximum=maximum,rationale=reason,anchor=qa_anchors[p['key']][i-1],reviewer='Codex-GroupB',second_score='',reconciled_score='',status='first_review_only',checked_at_utc=TS,independent_checker='',reconciliation_status='pending'))
  for workload,base,metric,val,unit,anchor,caveat in p['outcomes']:
   oid='GB-O'+str(1+max(int(x['outcome_id'][4:]) for x in ex)).zfill(3)
   ex.append(dict(report_id=rid,outcome_id=oid,mechanism=p['mechanism'],hardware=p['gpu'],workload=workload,baseline=base,metric=metric,value=val,units=unit,source_anchor=anchor,caveat=caveat,reviewer='Codex-GroupB',check_status='source_checked_first_reviewer; independent_check_pending',checked_at_utc=TS,independent_checker='',final_decision='pending',evidence_scope='within-one-GPU result;see caveat',independent_checked_at_utc=''))
  reasons=['Peer-reviewed venue/year and publication identity checked.','Local GPU scheduler shares one device across model clients.','Inference workloads explicit.','Defined outcome with conditions and comparator.','Within-one-GPU experiment identified.','Publication year falls within2020-2026 window.']
  for i,reason in enumerate(reasons,1):criteria.append(dict(report_id=rid,criterion='IC'+str(i),source_anchor=p['anchor'] if i>1 else 'First source page; venue/DOI block',first_review_basis=reason,criterion_check_required='Independent confirmation',reviewer='Codex-GroupB',status='first_review_pass;independent_pending',independent_vote='',checker='',checked_at_utc=TS,final_decision='pending'))
  tasks.append(dict(report_id=rid,title=p['title'],source=p['url'],eligibility_task='Independently verify IC1-IC6',outcome_task='Verify registered outcomes and scope',quality_task='Independently score Q1-Q10',checker='',checked_at_utc='',reconciliation_status='pending',final_decision='pending'))
  for r in records:
   if r['canonical_record_id']==p['record']:links.append(dict(report_id=rid,record_id=r['record_id'],canonical_record_id=p['record'],provisional_study_id=form['study_id'],doi=p['doi'],study_linkage_status='provisional;not_final_inclusion'))
  retr=[x for x in retr if x['candidate']!=p['key']]
  retr.append(dict(candidate=p['key'],source_url=p['url'],checked_at_utc=TS,assessor='Codex-GroupB',retrieval_status='retrieved',sha256=hashlib.sha256(pdf.read_bytes()).hexdigest(),method='public author or repository PDF',assessment_status='selected_sections_assessed;independent_pending',licensed_source_in_git='no'))
 for n,rs in [('fulltext_checks.csv',checks),('study_extraction_form.csv',forms),('quality.csv',qa),('extraction.csv',ex),('fulltext_criteria.csv',criteria),('report_validation_queue.csv',tasks),('report_record_links.csv',links),('cycle3_retrieval.csv',retr)]:write(n,rs)
 # Empty outputs are deliberate: pending review is never converted to a false zero-study finding.
 if not (E/'validated_studies.csv').exists():write('validated_studies.csv',[],['study_id','report_id','validation_evidence','reviewer_1','reviewer_2','final_decision'])
 write('fulltext_exclusions.csv',[dict(report_id=x['report_id'],criterion=x.get('primary_exclusion',''),reason=x['criterion_rationale'],assessor=x['reviewer'],decision_status='first_review_proposal;independent_pending') for x in checks if x['first_reviewer_recommendation']=='exclude_recommendation'],['report_id','criterion','reason','assessor','decision_status'])
 write('provisional_studies.csv',[dict(report_id=x['report_id'],title=x['title'],doi=x['doi'],study_id=x['study_id'],eligibility_status=x['eligibility_status'],final_decision='pending',source=x['source'],source_anchor=x['source_anchor']) for x in forms])
 print(json.dumps(dict(reports=len(checks),qa_items=len(qa),outcomes=len(ex))))
if __name__=='__main__':
 import sys;assess(sys.argv[1:] or ['paella','orion','gslice','clockwork'])
